+/* PT Contoh — company profile */
+:root {
+  --primary: #1d4ed8;
+  --primary-dark: #1e3a8a;
+  --bg: #f8fafc;
+  --surface: #ffffff;
+  --text: #0f172a;
+  --muted: #64748b;
+  --radius: 10px;
+}
+
+* { box-sizing: border-box; margin: 0; padding: 0; }
+
+body {
+  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
+  color: var(--text);
+  background: var(--bg);
+  line-height: 1.6;
+}
+
+.container { max-width: 1100px; margin: 0 auto; padding: 0 1.25rem; }
+
+.site-header {
+  position: sticky;
+  top: 0;
+  background: var(--surface);
+  border-bottom: 1px solid #e2e8f0;
+  z-index: 10;
+}
+
+.nav-wrap { display: flex; align-items: center; justify-content: space-between; height: 64px; }
+
+.logo { font-size: 1.25rem; font-weight: 800; color: var(--primary); text-decoration: none; }
+
+.nav { display: flex; gap: 1.25rem; flex-wrap: wrap; }
+.nav a { color: var(--text); text-decoration: none; font-weight: 500; }
+.nav a:hover { color: var(--primary); }
+
+.hero {
+  background: linear-gradient(135deg, var(--primary), var(--primary-dark));
+  color: #fff;
+  padding: 5rem 0;
+  text-align: center;
+}
+.hero h1 { font-size: 2.25rem; margin-bottom: .75rem; }
+.hero p { max-width: 600px; margin: 0 auto 1.5rem; opacity: .9; }
+.hero .btn { background: #fff; color: var(--primary); }
+
+.btn {
+  display: inline-block;
+  padding: .65rem 1.5rem;
+  border: none;
+  border-radius: var(--radius);
+  background: var(--primary);
+  color: #fff;
+  font-size: 1rem;
+  font-weight: 600;
+  text-decoration: none;
+  cursor: pointer;
+}
+.btn:hover { filter: brightness(1.1); }
+
+.section { padding: 4rem 0; }
+.section.alt { background: var(--surface); }
+.section h2 { font-size: 1.75rem; margin-bottom: 1.5rem; }
+
+.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 2rem; }
+
+.card {
+  background: var(--surface);
+  border: 1px solid #e2e8f0;
+  border-radius: var(--radius);
+  padding: 1.5rem;
+}
+.section.alt .card { background: var(--bg); }
+.card h3 { margin-bottom: .75rem; }
+.card p { margin-bottom: .5rem; }
+
+.facts { list-style: none; display: grid; gap: .5rem; }
+
+/* Katalog produk */
+.filters { display: flex; gap: .5rem; flex-wrap: wrap; margin-bottom: 1.5rem; }
+
+.chip {
+  padding: .4rem 1rem;
+  border: 1px solid #cbd5e1;
+  border-radius: 999px;
+  background: var(--surface);
+  color: var(--text);
+  font-size: .9rem;
+  cursor: pointer;
+}
+.chip.active { background: var(--primary); border-color: var(--primary); color: #fff; }
+
+.grid-products {
+  display: grid;
+  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
+  gap: 1.25rem;
+}
+
+.product-card {
+  background: var(--surface);
+  border: 1px solid #e2e8f0;
+  border-radius: var(--radius);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+}
+.product-img {
+  height: 150px;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 3rem;
+  background: #eef2ff;
+}
+.product-body { padding: 1rem; display: flex; flex-direction: column; gap: .35rem; flex: 1; }
+.product-body h3 { font-size: 1.05rem; }
+.product-cat { font-size: .8rem; color: var(--muted); text-transform: uppercase; letter-spacing: .03em; }
+.product-price { font-weight: 700; color: var(--primary); margin-top: auto; }
+.product-empty { grid-column: 1 / -1; color: var(--muted); text-align: center; padding: 2rem 0; }
+
+/* Form kontak */
+#contact-form { display: flex; flex-direction: column; gap: .5rem; }
+#contact-form label { font-weight: 600; font-size: .9rem; margin-top: .5rem; }
+#contact-form input,
+#contact-form textarea {
+  padding: .6rem .75rem;
+  border: 1px solid #cbd5e1;
+  border-radius: 8px;
+  font: inherit;
+}
+#contact-form input:focus,
+#contact-form textarea:focus { outline: 2px solid var(--primary); outline-offset: 1px; }
+.form-status { min-height: 1.4em; font-size: .9rem; color: #15803d; }
+.form-status.error { color: #b91c1c; }
+
+.site-footer { background: var(--primary-dark); color: #c7d2fe; padding: 1.5rem 0; text-align: center; }
+
+@media (max-width: 720px) {
+  .grid-2 { grid-template-columns: 1fr; }
+  .hero h1 { font-size: 1.75rem; }
+}
--- a//home/xyconix11x/Ayid/xyconix11x/Skripsi/Daedalus/jojo/script.js
