+// Katalog produk PT Contoh
+const PRODUCTS = [
+  { id: 1, nama: "Laptop Kerja Pro", kategori: "elektronik", harga: 12500000, emoji: "💻", desc: "Laptop bisnis ringan, RAM 16GB, SSD 512GB." },
+  { id: 2, nama: "Router Gigabit", kategori: "elektronik", harga: 850000, emoji: "🌐", desc: "Router dual-band untuk jaringan kantor stabil." },
+  { id: 3, nama: "Kamera CCTV HD", kategori: "elektronik", harga: 1450000, emoji: "📷", desc: "Kamera pengawas 1080p dengan night vision." },
+  { id: 4, nama: "Obeng Set Lengkap", kategori: "perkakas", harga: 120000, emoji: "🔧", desc: "Set obeng 32 pcs untuk perbaikan presisi." },
+  { id: 5, nama: "Bor Listrik 650W", kategori: "perkakas", harga: 675000, emoji: "🔨", desc: "Bor tangan bertenaga untuk pekerjaan berat." },
+  { id: 6, nama: "Tang Hex Key Set", kategori: "perkakas", harga: 95000, emoji: "🪛", desc: "Set kunci hex 5–10 mm, baja chrome." },
+  { id: 7, nama: "Printer A4 Multifungsi", kategori: "kantor", harga: 2150000, emoji: "🖨️", desc: "Cetak, scan, dan fotokopi dalam satu alat." },
+  { id: 8, nama: "Buku Agenda 2025", kategori: "kantor", harga: 45000, emoji: "📓", desc: "Agenda harian hardcover isi 368 halaman." },
+  { id: 9, nama: "Stapler Heavy Duty", kategori: "kantor", harga: 78000, emoji: "📎", desc: "Stapler kapasitas 100 lembar." },
+];
+
+const formatRupiah = (n) => "Rp " + n.toLocaleString("id-ID");
+
+function renderProducts(filter) {
+  const grid = document.getElementById("product-grid");
+  const items = filter === "semua" ? PRODUCTS : PRODUCTS.filter((p) => p.kategori === filter);
+
+  grid.innerHTML = "";
+  if (items.length === 0) {
+    const empty = document.createElement("p");
+    empty.className = "product-empty";
+    empty.textContent = "Tidak ada produk pada kategori ini.";
+    grid.appendChild(empty);
+    return;
+  }
+
+  for (const p of items) {
+    const card = document.createElement("article");
+    card.className = "product-card";
+
+    const img = document.createElement("div");
+    img.className = "product-img";
+    img.setAttribute("aria-hidden", "true");
+    img.textContent = p.emoji;
+
+    const body = document.createElement("div");
+    body.className = "product-body";
+
+    const cat = document.createElement("span");
+    cat.className = "product-cat";
+    cat.textContent = p.kategori;
+
+    const title = document.createElement("h3");
+    title.textContent = p.nama;
+
+    const desc = document.createElement("p");
+    desc.textContent = p.desc;
+
+    const price = document.createElement("p");
+    price.className = "product-price";
+    price.textContent = formatRupiah(p.harga);
+
+    body.append(cat, title, desc, price);
+    card.append(img, body);
+    grid.appendChild(card);
+  }
+}
+
+function initCatalog() {
+  const chips = document.querySelectorAll(".chip");
+  chips.forEach((chip) => {
+    chip.addEventListener("click", () => {
+      chips.forEach((c) => c.classList.remove("active"));
+      chip.classList.add("active");
+      renderProducts(chip.dataset.filter);
+    });
+  });
+  renderProducts("semua");
+}
+
+function initContactForm() {
+  const form = document.getElementById("contact-form");
+  const status = document.getElementById("form-status");
+  form.addEventListener("submit", (e) => {
+    e.preventDefault();
+    if (!form.checkValidity()) {
+      status.textContent = "Isi semua kolom dengan benar.";
+      status.classList.add("error");
+      return;
+    }
+    status.classList.remove("error");
+    status.textContent = "Pesan terkirim! Tim kami akan segera merespons.";
+    form.reset();
+  });
+}
+
+document.addEventListener("DOMContentLoaded", () => {
+  initCatalog();
+  initContactForm();
+});
